{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE VAHDAM_DB.MAPLEMONK1.VAHDAM_WALMART_3P_US_PNL_FY27 AS WITH orders_dedup AS ( SELECT * FROM VAHDAM_DB.MAPLEMONK1.WALMART_3P_US_GET_WFS_FULFILLED_ORDERS QUALIFY ROW_NUMBER() OVER (PARTITION BY PURCHASEORDERID ORDER BY _AIRBYTE_EMITTED_AT DESC) = 1 ), order_line AS ( SELECT o.PURCHASEORDERID AS po, l.index AS line_idx, CONVERT_TIMEZONE(\'UTC\',\'America/Los_Angeles\', DATEADD(ms, o.ORDERDATE::NUMBER,\'1970-01-01\'::TIMESTAMP_NTZ))::DATE AS day, l.value:item:sku::STRING AS sku, l.value:orderLineQuantity:amount::NUMBER AS qty, COALESCE(l.value:incentive:walmartFundedIncentive:amount::FLOAT,0) AS wfi_unit, l.value:orderLineStatuses:orderLineStatus[0]:status::STRING AS line_status, l.value AS line FROM orders_dedup o, LATERAL FLATTEN(input => o.ORDERLINES:orderLine) l ), line_charges AS ( SELECT ol.po, ol.line_idx, ol.day, ol.sku, ol.qty, ol.wfi_unit, ol.line_status, SUM(CASE WHEN c.value:chargeName::STRING = \'ItemPrice\' THEN c.value:chargeAmount:amount::FLOAT ELSE 0 END) AS item_price FROM order_line ol, LATERAL FLATTEN(input => ol.line:charges:charge) c GROUP BY 1,2,3,4,5,6,7 ), line_refunds AS ( SELECT ol.po, ol.line_idx, SUM(CASE WHEN rc.value:charge:chargeName::STRING = \'ItemPrice\' THEN rc.value:charge:chargeAmount:amount::FLOAT ELSE 0 END) AS refund_amt FROM order_line ol, LATERAL FLATTEN(input => ol.line:refund:refundCharges:refundCharge) rc GROUP BY 1,2 ), sales_daily AS ( SELECT lc.day, lc.sku, SUM(CASE WHEN lc.line_status <> \'Cancelled\' THEN lc.qty ELSE 0 END) AS qty_actual, SUM(CASE WHEN lc.line_status <> \'Cancelled\' THEN lc.item_price - lc.wfi_unit * lc.qty ELSE 0 END) AS gross_sales_usd, SUM(CASE WHEN lc.line_status <> \'Cancelled\' THEN lc.item_price ELSE 0 END) AS item_price_usd, SUM(CASE WHEN lc.line_status <> \'Cancelled\' THEN -lc.wfi_unit * lc.qty ELSE 0 END) AS wm_funded_usd, SUM(COALESCE(lr.refund_amt,0)) AS refund_usd, SUM(CASE WHEN lc.line_status = \'Cancelled\' THEN lc.qty ELSE 0 END) AS cancelled_units FROM line_charges lc LEFT JOIN line_refunds lr ON lr.po = lc.po AND lr.line_idx = lc.line_idx GROUP BY 1,2 ), sku_map AS ( SELECT TRIM(\"Walmart US\") AS sku, ANY_VALUE(BRAND) AS brand, ANY_VALUE(TRIM(\"Common SKU ID\")) AS common_sku_id, ANY_VALUE(\"Common SKU Description\") AS common_sku_description, ANY_VALUE(CATEGORY) AS category, ANY_VALUE(\"Sub-category\") AS sub_category, ANY_VALUE(\"Type-3\") AS wmt_category FROM VAHDAM_DB.MAPLEMONK.VAHDAM_FY27_INPUTS_PRODUCT_MAPPING WHERE NULLIF(TRIM(\"Walmart US\"),\'\') IS NOT NULL GROUP BY 1 ), cogs_sheet AS ( SELECT TRIM(MATERIAL) AS common_sku_id, AVG(TRY_TO_DECIMAL(REPLACE(COGS,\',\',\'\'),30,5)) AS cogs_per_unit_inr FROM VAHDAM_DB.MAPLEMONK.VAHDAM_FY27_INPUTS_COGS_SHEET WHERE MATERIAL IS NOT NULL GROUP BY 1 ), budget_raw AS ( SELECT TRIM(\"Lineitem sku\") AS sku, TRIM(\"Common SKU\") AS budget_common_sku, MONTH_DT AS month_start, \"Exchange\"::FLOAT AS fx, \"Qty\" AS qty, \"Net Sales\" AS net_sales_inr, \"COGS per unit\" AS cogs_per_unit_inr, \"COGS\" AS cogs_inr, \"Commission\" AS commission_inr, \"Outbound\" AS outbound_inr, \"3PL + Storage per unit\" AS tpl_storage_per_unit_inr, \"3PL + Storage\" AS tpl_storage_inr, \"Last Mile Per unit\" AS lastmile_per_unit_inr, \"Last mile\" AS lastmile_inr, \"Performance Marketing\" AS pm_inr, \"Add Tariff\" AS add_tariff_inr FROM VAHDAM_DB.MAPLEMONK1.OFFLINE_BUDGET_FY27 WHERE \"Platform\" = \'Walmart 3P\' AND UPPER(\"Geography\") = \'USA\' ), budget_sku AS ( SELECT sku, month_start, MAX(fx) AS fx, SUM(qty) AS qty_budget, SUM(net_sales_inr) AS net_sales_budget_inr, SUM(cogs_inr) AS cogs_budget_inr, SUM(commission_inr) AS commission_budget_inr, SUM(outbound_inr) AS outbound_budget_inr, SUM(tpl_storage_inr) AS tpl_storage_budget_inr, SUM(lastmile_inr) AS lastmile_budget_inr, SUM(pm_inr) AS pm_budget_inr, SUM(add_tariff_inr) AS add_tariff_budget_inr, AVG(cogs_per_unit_inr) AS cogs_per_unit_inr, DIV0(SUM(outbound_inr), NULLIF(SUM(qty),0)) AS outbound_per_unit_inr, AVG(tpl_storage_per_unit_inr) AS tpl_storage_per_unit_inr, AVG(lastmile_per_unit_inr) AS lastmile_per_unit_inr, DIV0(SUM(commission_inr), NULLIF(SUM(net_sales_inr),0)) AS commission_pct_budget, CASE WHEN COALESCE(SUM(add_tariff_inr),0) > 0 THEN 1 ELSE 0 END AS has_additional_duty_flag FROM budget_raw WHERE month_start IS NOT NULL AND NULLIF(sku,\'\') IS NOT NULL GROUP BY 1,2 ), budget_pkg AS ( SELECT LEFT(m.common_sku_id,6) AS pkg6, b.month_start, AVG(b.outbound_per_unit_inr) AS outbound_per_unit_inr_pkg FROM budget_sku b JOIN sku_map m ON m.sku = b.sku WHERE LENGTH(m.common_sku_id) >= 6 GROUP BY 1,2 ), fx_map AS (SELECT month_start, MAX(fx) AS fx FROM budget_raw WHERE fx IS NOT NULL AND month_start IS NOT NULL GROUP BY 1), fx_overall AS (SELECT AVG(fx) AS fx_avg FROM fx_map), sem_dedup AS ( SELECT DISTINCT DATE, \"Campaign ID\", SKU, \"Item ID\", \"Ad Spend\", SALES, CLICKS, IMPRESSIONS FROM VAHDAM_DB.MAPLEMONK1.WALMART_3P_US_GET_SEM_PERFORMANCE_REPORT ), sem_daily AS ( SELECT TRY_TO_DATE(DATE) AS day, SKU AS sku, SUM(TRY_TO_DOUBLE(\"Ad Spend\")) AS spend, SUM(TRY_TO_DOUBLE(SALES)) AS ad_sales, SUM(TRY_TO_DOUBLE(CLICKS)) AS clicks, SUM(TRY_TO_DOUBLE(IMPRESSIONS)) AS impressions FROM sem_dedup WHERE TRY_TO_DATE(DATE) IS NOT NULL AND NULLIF(SKU,\'\') IS NOT NULL GROUP BY 1,2 ), item_sku_bridge AS ( SELECT item_id, ANY_VALUE(sku) AS sku FROM ( SELECT \"Item ID\" AS item_id, SKU AS sku FROM sem_dedup WHERE NULLIF(\"Item ID\",\'\') IS NOT NULL AND NULLIF(SKU,\'\') IS NOT NULL UNION ALL SELECT ITEMID, SKU FROM VAHDAM_DB.MAPLEMONK1.WALMART_3P_US_GET_ITEM_LEVEL_PERFORMANCE_DATA WHERE NULLIF(ITEMID,\'\') IS NOT NULL AND NULLIF(SKU,\'\') IS NOT NULL ) GROUP BY 1 ), connect_item AS ( SELECT \"c_DATE\" AS day, ITEMID_ST AS item_id, SUM(TRY_TO_DOUBLE(ADSPEND_ST)) AS spend, SUM(TRY_TO_DOUBLE(ATTRIBUTEDSALES14DAYS_ST)) AS ad_sales, SUM(TRY_TO_DOUBLE(NUMADSCLICKS)) AS clicks, SUM(TRY_TO_DOUBLE(NUMADSSHOWN)) AS impressions FROM (SELECT * FROM DATON.RAW.WALMART_CONNECT_US_ADITEMSNAPSHOTREPORT QUALIFY ROW_NUMBER() OVER (PARTITION BY \"c_DATE\",CAMPAIGNID_ST,ADGROUPID_ST,ITEMID_ST ORDER BY DATON_BATCH_ID DESC) = 1) GROUP BY 1,2 ), connect_group_day AS ( SELECT \"c_DATE\" AS day, SUM(TRY_TO_DOUBLE(ADSPEND_ST)) AS group_spend FROM (SELECT * FROM DATON.RAW.WALMART_CONNECT_US_ADGROUPSNAPSHOTREPORT QUALIFY ROW_NUMBER() OVER (PARTITION BY \"c_DATE\",CAMPAIGNID_ST,ADGROUPID_ST ORDER BY DATON_BATCH_ID DESC) = 1) GROUP BY 1 ), connect_item_day AS (SELECT day, SUM(spend) AS item_spend FROM connect_item GROUP BY 1), ad_floor AS (SELECT MIN(day) AS floor_day FROM sales_daily), ad_sku_direct AS ( SELECT day, sku, SUM(spend) AS spend, SUM(ad_sales) AS ad_sales, SUM(clicks) AS clicks, SUM(impressions) AS impressions FROM ( SELECT ci.day, b.sku, ci.spend, ci.ad_sales, ci.clicks, ci.impressions FROM connect_item ci JOIN item_sku_bridge b ON b.item_id = ci.item_id UNION ALL SELECT day, sku, spend, ad_sales, clicks, impressions FROM sem_daily ) WHERE day >= (SELECT floor_day FROM ad_floor) GROUP BY 1,2 ), ad_residual_day AS ( SELECT d.day, GREATEST(COALESCE(g.group_spend,0) - COALESCE(i.item_spend,0), 0) + COALESCE(u.unmapped_spend,0) AS residual_spend FROM (SELECT day FROM connect_group_day UNION SELECT day FROM connect_item_day) d LEFT JOIN connect_group_day g ON g.day = d.day LEFT JOIN connect_item_day i ON i.day = d.day LEFT JOIN (SELECT ci.day, SUM(ci.spend) AS unmapped_spend FROM connect_item ci LEFT JOIN item_sku_bridge b ON b.item_id = ci.item_id WHERE b.sku IS NULL GROUP BY 1) u ON u.day = d.day WHERE d.day >= (SELECT floor_day FROM ad_floor) ), recon_sku_day AS ( SELECT \"Partner Item Id\" AS sku, TRY_TO_TIMESTAMP(\"Transaction Posted Timestamp\")::DATE AS d, SUM(CASE WHEN \"Amount Type\"=\'Product Price\' THEN TRY_TO_DOUBLE(AMOUNT) ELSE 0 END) AS price, SUM(CASE WHEN \"Amount Type\"=\'Commission on Product\' THEN TRY_TO_DOUBLE(AMOUNT) ELSE 0 END) AS commission, SUM(CASE WHEN \"Amount Type\"=\'Fee/Reimbursement\' THEN TRY_TO_DOUBLE(AMOUNT) ELSE 0 END) AS wfs_fee, SUM(CASE WHEN \"Amount Type\"=\'Product Price\' THEN TRY_TO_DOUBLE(\"Ship Qty\") ELSE 0 END) AS ship_qty FROM VAHDAM_DB.MAPLEMONK1.WALMART_3P_US_GET_RECON_REPORT WHERE \"Transaction Type\" IN (\'Sale\',\'Adjustment\') AND NULLIF(\"Partner Item Id\",\'\') IS NOT NULL AND TRY_TO_TIMESTAMP(\"Transaction Posted Timestamp\") IS NOT NULL GROUP BY 1,2 ), recon_commission_latest AS ( SELECT sku, -1 * commission / price AS commission_pct_recon FROM recon_sku_day WHERE price <> 0 QUALIFY ROW_NUMBER() OVER (PARTITION BY sku ORDER BY d DESC) = 1 ), recon_lastmile_latest AS ( SELECT sku, -1 * wfs_fee / ship_qty AS lastmile_per_unit_usd_recon FROM recon_sku_day WHERE ship_qty <> 0 AND wfs_fee <> 0 QUALIFY ROW_NUMBER() OVER (PARTITION BY sku ORDER BY d DESC) = 1 ), month_spine AS ( SELECT DISTINCT month_start FROM budget_raw WHERE month_start IS NOT NULL UNION SELECT DISTINCT DATE_TRUNC(\'MONTH\', day) FROM sales_daily WHERE day IS NOT NULL UNION SELECT DISTINCT DATE_TRUNC(\'MONTH\', day) FROM ad_sku_direct WHERE day IS NOT NULL ), budget_sku_keys AS (SELECT DISTINCT sku FROM budget_sku), budget_sku_ff AS ( SELECT s.month_start, k.sku, LAST_VALUE(b.cogs_per_unit_inr) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cogs_per_unit_inr_ff, LAST_VALUE(b.outbound_per_unit_inr) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS outbound_per_unit_inr_ff, LAST_VALUE(b.tpl_storage_per_unit_inr) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS tpl_storage_per_unit_inr_ff, LAST_VALUE(b.lastmile_per_unit_inr) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS lastmile_per_unit_inr_ff, LAST_VALUE(b.commission_pct_budget) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS commission_pct_budget_ff, LAST_VALUE(b.has_additional_duty_flag) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS has_additional_duty_flag_ff, LAST_VALUE(CASE WHEN b.sku IS NOT NULL THEN s.month_start END) IGNORE NULLS OVER (PARTITION BY k.sku ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS budget_month_used FROM month_spine s CROSS JOIN budget_sku_keys k LEFT JOIN budget_sku b ON b.sku = k.sku AND b.month_start = s.month_start ), budget_pkg_keys AS (SELECT DISTINCT pkg6 FROM budget_pkg), budget_pkg_ff AS ( SELECT s.month_start, k.pkg6, LAST_VALUE(p.outbound_per_unit_inr_pkg) IGNORE NULLS OVER (PARTITION BY k.pkg6 ORDER BY s.month_start ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS outbound_per_unit_inr_pkg_ff FROM month_spine s CROSS JOIN budget_pkg_keys k LEFT JOIN budget_pkg p ON p.pkg6 = k.pkg6 AND p.month_start = s.month_start ), budget_days AS ( SELECT month_start, DAY(LAST_DAY(month_start)) AS days_in_month FROM (SELECT DISTINCT month_start FROM budget_raw WHERE month_start IS NOT NULL) ), day_offsets AS (SELECT SEQ4() AS d_off FROM TABLE(GENERATOR(ROWCOUNT => 31))), budget_daily AS ( SELECT DATEADD(day, o.d_off, b.month_start) AS day, b.sku, b.qty_budget / NULLIF(d.days_in_month,0) AS qty_budget, b.net_sales_budget_inr / NULLIF(d.days_in_month,0) AS sales_budget_inr, b.cogs_budget_inr / NULLIF(d.days_in_month,0) AS cogs_budget_inr, b.commission_budget_inr / NULLIF(d.days_in_month,0) AS commission_budget_inr, b.outbound_budget_inr / NULLIF(d.days_in_month,0) AS outbound_budget_inr, b.tpl_storage_budget_inr/ NULLIF(d.days_in_month,0) AS tpl_storage_budget_inr, b.lastmile_budget_inr / NULLIF(d.days_in_month,0) AS lastmile_budget_inr, b.add_tariff_budget_inr / NULLIF(d.days_in_month,0) AS add_tariff_budget_inr, b.pm_budget_inr / NULLIF(d.days_in_month,0) AS pm_budget_inr FROM budget_sku b JOIN budget_days d ON d.month_start = b.month_start JOIN day_offsets o ON o.d_off < d.days_in_month ), day_sales_pre AS (SELECT day, SUM(gross_sales_usd) AS day_sales FROM sales_daily GROUP BY day), unalloc_keys AS ( SELECT r.day, \'__UNALLOCATED__\' AS sku FROM ad_residual_day r LEFT JOIN day_sales_pre ds ON ds.day = r.day WHERE COALESCE(ds.day_sales,0) = 0 AND COALESCE(r.residual_spend,0) > 0 ), universe AS ( SELECT day, sku FROM sales_daily UNION SELECT day, sku FROM budget_daily UNION SELECT day, sku FROM ad_sku_direct UNION SELECT day, sku FROM unalloc_keys ), pass1 AS ( SELECT u.day, u.sku, DATE_TRUNC(\'MONTH\', u.day) AS month_start, m.brand, m.common_sku_id, m.common_sku_description, m.category, m.sub_category, m.wmt_category, COALESCE(fxm.fx, fxo.fx_avg) AS fx_inr, s.qty_actual, s.gross_sales_usd, s.item_price_usd, s.wm_funded_usd, s.refund_usd, s.cancelled_units, bff.cogs_per_unit_inr_ff AS cogs_budget_pu_inr, cs.cogs_per_unit_inr * 1.10 AS cogs_sheet_pu_inr, COALESCE(bff.cogs_per_unit_inr_ff, cs.cogs_per_unit_inr * 1.10) AS cogs_per_unit_inr_p1, bff.outbound_per_unit_inr_ff AS ob_sku_inr, COALESCE(bff.outbound_per_unit_inr_ff, bpf.outbound_per_unit_inr_pkg_ff) AS outbound_per_unit_inr_p1, bff.tpl_storage_per_unit_inr_ff AS tpl_storage_per_unit_inr_p1, COALESCE(rl.lastmile_per_unit_usd_recon * COALESCE(fxm.fx, fxo.fx_avg), bff.lastmile_per_unit_inr_ff) AS lastmile_per_unit_inr_p1, CASE WHEN rl.lastmile_per_unit_usd_recon IS NOT NULL THEN \'RECON\' WHEN bff.lastmile_per_unit_inr_ff IS NOT NULL THEN \'BUDGET_SKU\' ELSE NULL END AS lastmile_source, COALESCE(rc.commission_pct_recon, bff.commission_pct_budget_ff) AS commission_pct_p1, CASE WHEN rc.commission_pct_recon IS NOT NULL THEN \'RECON\' WHEN bff.commission_pct_budget_ff IS NOT NULL THEN \'BUDGET_SKU\' ELSE NULL END AS commission_source, COALESCE(bff.has_additional_duty_flag_ff,0) AS has_additional_duty_flag, bff.budget_month_used, COALESCE(ad.spend,0) AS pm_spend_direct_usd, COALESCE(ad.ad_sales,0) AS ad_sales_usd, COALESCE(ad.clicks,0) AS clicks, COALESCE(ad.impressions,0) AS impressions, arr.residual_spend AS residual_spend_day_usd, bd.qty_budget, bd.sales_budget_inr, bd.cogs_budget_inr, bd.commission_budget_inr, bd.outbound_budget_inr, bd.tpl_storage_budget_inr, bd.lastmile_budget_inr, bd.add_tariff_budget_inr, bd.pm_budget_inr FROM universe u LEFT JOIN sales_daily s ON s.day = u.day AND s.sku = u.sku LEFT JOIN sku_map m ON m.sku = u.sku LEFT JOIN cogs_sheet cs ON cs.common_sku_id = m.common_sku_id LEFT JOIN budget_sku_ff bff ON bff.sku = u.sku AND bff.month_start = DATE_TRUNC(\'MONTH\',u.day) LEFT JOIN budget_pkg_ff bpf ON bpf.pkg6 = LEFT(m.common_sku_id,6) AND bpf.month_start = DATE_TRUNC(\'MONTH\',u.day) LEFT JOIN budget_daily bd ON bd.day = u.day AND bd.sku = u.sku LEFT JOIN recon_commission_latest rc ON rc.sku = u.sku LEFT JOIN recon_lastmile_latest rl ON rl.sku = u.sku LEFT JOIN ad_sku_direct ad ON ad.day = u.day AND ad.sku = u.sku LEFT JOIN ad_residual_day arr ON arr.day = u.day LEFT JOIN fx_map fxm ON fxm.month_start = DATE_TRUNC(\'MONTH\',u.day) CROSS JOIN fx_overall fxo ), actuals_pct AS ( SELECT month_start, DIV0(SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL THEN qty_actual*cogs_per_unit_inr_p1 END), NULLIF(SUM(CASE WHEN cogs_per_unit_inr_p1 IS NOT NULL THEN gross_sales_usd*fx_inr END),0)) AS cogs_pct_actual, DIV0(SUM(CASE WHEN outbound_per_unit_inr_p1 IS NOT NULL THEN qty_actual*outbound_per_unit_inr_p1 END), NULLIF(SUM(CASE WHEN outbound_per_unit_inr_p1 IS NOT NULL THEN gross_sales_usd*fx_inr END),0)) AS outbound_pct_actual, DIV0(SUM(CASE WHEN tpl_storage_per_unit_inr_p1 IS NOT NULL THEN qty_actual*tpl_storage_per_unit_inr_p1 END), NULLIF(SUM(CASE WHEN tpl_storage_per_unit_inr_p1 IS NOT NULL THEN gross_sales_usd*fx_inr END),0)) AS tpl_storage_pct_actual, DIV0(SUM(CASE WHEN lastmile_per_unit_inr_p1 IS NOT NULL THEN qty_actual*lastmile_per_unit_inr_p1 END), NULLIF(SUM(CASE WHEN lastmile_per_unit_inr_p1 IS NOT NULL THEN gross_sales_usd*fx_inr END),0)) AS lastmile_pct_actual, DIV0(SUM(CASE WHEN commission_pct_p1 IS NOT NULL THEN gross_sales_usd*commission_pct_p1 END), NULLIF(SUM(CASE WHEN commission_pct_p1 IS NOT NULL THEN gross_sales_usd END),0)) AS commission_pct_actual FROM pass1 GROUP BY month_start ), day_sales AS (SELECT day, SUM(gross_sales_usd) AS day_sales FROM pass1 GROUP BY day), final AS ( SELECT p.*, COALESCE(p.cogs_per_unit_inr_p1, p.gross_sales_usd*p.fx_inr*ap.cogs_pct_actual/NULLIF(p.qty_actual,0)) AS cogs_per_unit_inr_used, COALESCE(p.outbound_per_unit_inr_p1, p.gross_sales_usd*p.fx_inr*ap.outbound_pct_actual/NULLIF(p.qty_actual,0)) AS outbound_per_unit_inr_used, COALESCE(p.tpl_storage_per_unit_inr_p1, p.gross_sales_usd*p.fx_inr*ap.tpl_storage_pct_actual/NULLIF(p.qty_actual,0)) AS tpl_storage_per_unit_inr_used, COALESCE(p.lastmile_per_unit_inr_p1, p.gross_sales_usd*p.fx_inr*ap.lastmile_pct_actual/NULLIF(p.qty_actual,0)) AS lastmile_per_unit_inr_used, COALESCE(p.commission_pct_p1, ap.commission_pct_actual) AS commission_pct_used, CASE WHEN p.sku = \'__UNALLOCATED__\' THEN COALESCE(p.residual_spend_day_usd,0) ELSE COALESCE(p.residual_spend_day_usd,0) * DIV0(p.gross_sales_usd, COALESCE(ds.day_sales,0)) END AS pm_spend_residual_usd FROM pass1 p LEFT JOIN actuals_pct ap ON ap.month_start = p.month_start LEFT JOIN day_sales ds ON ds.day = p.day ) SELECT day, \'Walmart_3P\' AS channel, \'USA\' AS geo, sku, brand, common_sku_id, common_sku_description, category, sub_category, wmt_category AS WMT_Category, \'USD\' AS currency_local, fx_inr, qty_actual, cancelled_units, item_price_usd AS item_price_actual_local, wm_funded_usd AS wm_funded_incentive_actual_local, gross_sales_usd AS sales_actual_local_gross, refund_usd AS refund_actual_local, gross_sales_usd + COALESCE(refund_usd,0) AS sales_actual_local, qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0) AS cogs_actual_local, CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(gross_sales_usd,0) * 0.10 * 0.25 ELSE 0 END AS additional_duty_actual_local, qty_actual * outbound_per_unit_inr_used / NULLIF(fx_inr,0) AS outbound_actual_local, qty_actual * tpl_storage_per_unit_inr_used / NULLIF(fx_inr,0) AS three_pl_storage_actual_local, qty_actual * lastmile_per_unit_inr_used / NULLIF(fx_inr,0) AS last_mile_actual_local, gross_sales_usd * commission_pct_used AS commission_actual_local, ( gross_sales_usd + COALESCE(refund_usd,0) - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(gross_sales_usd,0)*0.10*0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * tpl_storage_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * lastmile_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(gross_sales_usd * commission_pct_used,0) ) AS cm1_actual_local, pm_spend_direct_usd AS pm_spend_direct_local, pm_spend_residual_usd AS pm_spend_residual_local, COALESCE(pm_spend_direct_usd,0) + COALESCE(pm_spend_residual_usd,0) AS pm_spend_actual_local, ad_sales_usd AS ad_sales_actual_local, clicks, impressions, 0::FLOAT AS tool_cost_actual_local, ( gross_sales_usd + COALESCE(refund_usd,0) - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(gross_sales_usd,0)*0.10*0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * tpl_storage_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * lastmile_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(gross_sales_usd * commission_pct_used,0) ) - COALESCE(pm_spend_direct_usd,0) - COALESCE(pm_spend_residual_usd,0) AS cm2_actual_local, (gross_sales_usd + COALESCE(refund_usd,0)) * fx_inr AS sales_actual_inr, qty_actual * cogs_per_unit_inr_used AS cogs_actual_inr, CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(gross_sales_usd,0)*0.10*0.25*fx_inr ELSE 0 END AS additional_duty_actual_inr, qty_actual * outbound_per_unit_inr_used AS outbound_actual_inr, qty_actual * tpl_storage_per_unit_inr_used AS three_pl_storage_actual_inr, qty_actual * lastmile_per_unit_inr_used AS last_mile_actual_inr, gross_sales_usd * commission_pct_used * fx_inr AS commission_actual_inr, ( gross_sales_usd + COALESCE(refund_usd,0) - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(gross_sales_usd,0)*0.10*0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * tpl_storage_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * lastmile_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(gross_sales_usd * commission_pct_used,0) ) * fx_inr AS cm1_actual_inr, (COALESCE(pm_spend_direct_usd,0)+COALESCE(pm_spend_residual_usd,0)) * fx_inr AS pm_spend_actual_inr, (( gross_sales_usd + COALESCE(refund_usd,0) - COALESCE(qty_actual * cogs_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(CASE WHEN has_additional_duty_flag = 1 THEN COALESCE(gross_sales_usd,0)*0.10*0.25 ELSE 0 END,0) - COALESCE(qty_actual * outbound_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * tpl_storage_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(qty_actual * lastmile_per_unit_inr_used / NULLIF(fx_inr,0),0) - COALESCE(gross_sales_usd * commission_pct_used,0) ) - COALESCE(pm_spend_direct_usd,0) - COALESCE(pm_spend_residual_usd,0)) * fx_inr AS cm2_actual_inr, qty_budget, sales_budget_inr, cogs_budget_inr, add_tariff_budget_inr AS additional_duty_budget_inr, commission_budget_inr, outbound_budget_inr, tpl_storage_budget_inr AS three_pl_storage_budget_inr, lastmile_budget_inr AS last_mile_budget_inr, ( COALESCE(sales_budget_inr,0)-COALESCE(cogs_budget_inr,0)-COALESCE(add_tariff_budget_inr,0) -COALESCE(commission_budget_inr,0)-COALESCE(outbound_budget_inr,0) -COALESCE(tpl_storage_budget_inr,0)-COALESCE(lastmile_budget_inr,0) ) AS cm1_budget_inr, pm_budget_inr AS pm_spend_budget_inr, ( COALESCE(sales_budget_inr,0)-COALESCE(cogs_budget_inr,0)-COALESCE(add_tariff_budget_inr,0) -COALESCE(commission_budget_inr,0)-COALESCE(outbound_budget_inr,0) -COALESCE(tpl_storage_budget_inr,0)-COALESCE(lastmile_budget_inr,0) -COALESCE(pm_budget_inr,0) ) AS cm2_budget_inr, sales_budget_inr / NULLIF(fx_inr,0) AS sales_budget_local, commission_source, lastmile_source, CASE WHEN cogs_budget_pu_inr IS NOT NULL THEN \'BUDGET\' WHEN cogs_sheet_pu_inr IS NOT NULL THEN \'COGS_SHEET_x1.10\' WHEN cogs_per_unit_inr_used IS NOT NULL THEN \'SALES_WEIGHTED_AVG\' END AS cogs_source, CASE WHEN ob_sku_inr IS NOT NULL THEN \'BUDGET_SKU\' WHEN outbound_per_unit_inr_p1 IS NOT NULL THEN \'BUDGET_PKG6\' WHEN outbound_per_unit_inr_used IS NOT NULL THEN \'SALES_WEIGHTED_AVG\' END AS outbound_source, CASE WHEN budget_month_used IS NULL THEN \'NO_BUDGET\' WHEN budget_month_used <> month_start THEN \'Y\' ELSE \'N\' END AS budget_carried_forward, CASE WHEN sku = \'__UNALLOCATED__\' THEN \'AD_ONLY_UNALLOCATED\' WHEN COALESCE(qty_actual,0) = 0 AND COALESCE(pm_spend_direct_usd,0) > 0 THEN \'AD_ONLY_NO_SALES\' WHEN COALESCE(qty_actual,0) = 0 THEN \'NO_ACTUALS\' WHEN cogs_per_unit_inr_used IS NOT NULL AND commission_pct_used IS NOT NULL AND outbound_per_unit_inr_used IS NOT NULL AND lastmile_per_unit_inr_used IS NOT NULL AND tpl_storage_per_unit_inr_used IS NOT NULL THEN \'COMPLETE\' ELSE \'PARTIAL\' END AS cost_completeness FROM final ORDER BY day DESC, sales_actual_local_gross DESC NULLS LAST;",
